// Krimble 2026-11-08: the colored icons of the Color panel (the color models and the rows of the Values page), cut out of the mockups with the distance from the button color as transparency.
#pragma once
#include <QByteArray>
#include <QHash>
#include <QPixmap>
#include <QString>

inline QPixmap krimbleStudioIcon(const QString &name)
{
    static QHash<QString, QPixmap> cache;
    auto found = cache.constFind(name);
    if (found != cache.constEnd()) return found.value();
    static const struct { const char *name; const char *data; } icons[] = {
        { "model_rgb", "" },   // 58 x 55
        { "model_hsv", "" },   // 62 x 56
        { "model_hsl", "" },   // 53 x 55
        { "model_cmyk", "" },   // 62 x 52
        { "model_gray", "" },   // 47 x 54
        { "row_rgb", "" },   // 40 x 32
        { "row_hash", "" },   // 32 x 30
        { "row_eyedropper", "" },   // 37 x 38
        { "row_palette", "" },   // 36 x 35
        { "pin_off", "" },   // 42 x 40
        { "pin_on", "" },   // 34 x 38
        { "tool_brush", "" },   // 31 x 30
        { "tool_gradient", "" },   // 31 x 30
        { "tool_fill", "" },   // 33 x 34
        { "tool_picker", "" },   // 32 x 32
        { "filter", "" },   // 40 x 40
        { "list", "" },   // 39 x 38
        { "pin_title", "" },   // 29 x 29
        { "pin_button", "" },   // 40 x 39
        { "pal_new", "" },   // 48 x 30
        { "pal_open", "" },   // 48 x 33
        { "pal_import", "" },   // 48 x 29
        { "pal_export", "" },   // 48 x 30
        { "pal_duplicate", "" },   // 48 x 30
        { "pal_rename", "" },   // 48 x 33
        { "pal_delete", "" },   // 48 x 33
        { "pal_grid", "" },   // 48 x 39
        { "tool_eyedropper", "" },   // 60 x 55
        { "tool_pencil", "" },   // 60 x 54
        { "tool_refresh", "" },   // 54 x 43
        { "tool_grid", "" },   // 56 x 55
    };
    QPixmap pixmap;
    for (const auto &icon : icons) {
        if (name == QLatin1String(icon.name)) { pixmap.loadFromData(QByteArray::fromBase64(QByteArray(icon.data)), "PNG"); break; }
    }
    cache.insert(name, pixmap);
    return pixmap;
}
